    {
      "command": "seek_1",
      "condition": "is_walking and family_present and clock_hour >= 10 and clock_hour < 11",
      "place_labels": ["해든상가"],
      "hold_minutes": 0,
      "note_ids": ["N1"]
    }
  ],
  "non_action_note_ids": ["N0"]
